def median(xs: list[float]) -> float:
    """Median of a non-empty list. For even length, the mean of the two middle values."""
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    mid = n // 2
    if n % 2 == 1:
        return sorted_xs[mid]
    else:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2

def run_length(s: str) -> str:
    """Run-length encode: each maximal run of a character c of length k becomes c followed by k. 'aaab' -> 'a3b1'."""
    if not s:
        return ''

    result = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(current_char + str(count))
            current_char = s[i]
            count = 1

    # Don't forget the last run
    if current_char:
        result.append(current_char + str(count))

    return ''.join(result)

