def gcd(a: int, b: int) -> int:
    """Greatest common divisor of two non-negative integers, not both zero."""
    while b != 0:
        a, b = b, a % b
    return a

def flatten(xs: list) -> list:
    """Flatten arbitrarily nested lists into a single list, preserving order."""
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

